The tables show groups of identical rows that differ per skill, and skill 3 looks like a bitwise AND of hidden 4-bit codes, so I will cluster rows and columns per skill to read off the structure.
```python
import numpy as np
exec(open("/dev/null").read())
def silu(x): return x/(1+np.exp(-x))
def fwd(W, X):
    h=silu(X@W["l1.weight"].T+W["l1.bias"]); h=silu(h@W["l2.weight"].T+W["l2.bias"]); return h@W["l3.weight"].T+W["l3.bias"]
W={n:load(n) for n in NAMES}
def inp(s):
    X=np.zeros((1024,68))
    for a in range(32):
        for b in range(32):
            i=a*32+b; X[i,a]=1; X[i,32+b]=1; X[i,64+s]=1
    return X
T=np.stack([fwd(W,inp(s)).argmax(1).reshape(32,32) for s in range(4)])
np.save("tables.npy",T)
def clusters(M,th):
    n=len(M); lab=-np.ones(n,int); c=0
    for i in range(n):
        if lab[i]<0:
            lab[i]=c
            for j in range(i+1,n):
                if lab[j]<0 and (M[i]==M[j]).mean()>=th: lab[j]=c
            c+=1
    return lab
for s in range(4):
    for th in (0.9,0.75):
        ra=clusters(T[s],th); rb=clusters(T[s].T,th)
        print("skill",s,"th",th,"a-groups",ra.max()+1,"b-groups",rb.max()+1)
        print(" a",ra.tolist()); print(" b",rb.tolist())
