Skill 3 fits AND at 0.957 and skill 1 fits multiplication at 0.837, so I rerun with many more restarts and print skill 2 and skill 0 with similar rows grouped to read their rules.
```python
import numpy as np, time, pickle
T=np.load("tables.npy")
ops={"and":lambda x,y:x&y,"or":lambda x,y:x|y,"xor":lambda x,y:x^y,"add":lambda x,y:(x+y)%16,"sub":lambda x,y:(x-y)%16,"mul":lambda x,y:(x*y)%16,"max":np.maximum,"min":np.minimum}
X,Y=np.meshgrid(np.arange(16),np.arange(16),indexing="ij")
rng=np.random.default_rng(1)
res={}
def fit(F,Tt,starts):
    best=(-1,None,None)
    for st in range(starts):
        cb=rng.integers(0,F.shape[1],32)
        for it in range(15):
            ca=(F[:,cb][None,:,:]==Tt[:,None,:]).sum(2).argmax(1)
            cb=(F[ca][:,:,None]==Tt[:,None,:]).sum(0).argmax(0)
        ag=(F[ca][:,cb]==Tt).mean()
        if ag>best[0]: best=(ag,ca.copy(),cb.copy())
    return best
t0=time.time()
for s in range(4):
    out={}
    for name,f in ops.items():
        r=fit(f(X,Y),T[s],250); res[(s,name)]=r; out[name]=round(float(r[0]),3)
    print("skill",s,out,round(time.time()-t0,1))
pickle.dump(res,open("res.pkl","wb"))
for s,n in ((1,"mul"),(3,"and")):
    r=res[(s,n)]; print(s,n,round(r[0],3)); print(" a",r[1].tolist()); print(" b",r[2].tolist())
```
