T=np.load("tables.npy")
def order(M):
    # greedy nearest-neighbour ordering of rows
    n=len(M); left=list(range(1,n)); o=[0]
    while left:
        j=max(left,key=lambda k:(M[o[-1]]==M[k]).mean()); o.append(j); left.remove(j)
    return o
for s in (2,0):
    ra=order(T[s]); rb=order(T[s].T)
    print("skill",s,"rows",ra); print("cols",rb)
    S=T[s][ra][:,rb]
    print("\n".join("".join(f"{v:x}" if v<16 else "?" for v in row) for row in S))
